<style scoped lang="scss" src="./scroll-view.scss"></style
><style
  scoped
  lang="scss"
  src="../dropdown-menu/client-dropdown-menu.scss"
></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { ScrollBarSide, ScrollBarSideValues } from "./scroll-view.constants";
import { normalizeWheel } from "../../util/normalize-wheel";
import { has } from "../../util/has";

/**
 * Provides a customized scrolling solution to unify look and feel across
 * devices. This also fixes some user experiences with scrolling where the
 * scroll bar is inconvenient or otherwise useless.
 */
@Component
export default class ScrollView extends Vue {
  /** When set, the scroll will have some inertia for touch controls */
  @Prop({ type: Boolean }) allowTouchInertia;
  /** Apply a custom classname to the content portion of the scrollview */
  @Prop({ type: String }) contentClassName;
  /** This forces a maximum amount of scroll room */
  @Prop({ type: Number }) scrollHeight;
  /** Sets this scroll view to the given scroll top value */
  @Prop({ type: Number }) scrollTopOnce;
  /** Determines which side the scroll bar should appear on */
  @Prop({
    type: Number,
    default: ScrollBarSide.RIGHT,
    validator: has(ScrollBarSideValues)
  })
  side;

  observer = null;
  barTop = 0;
  isDragging = false;
  isOpen = false;
  bounds = null;
  contentBounds = null;
  childrenChanged = true;
  initialized = false;
  top = 0;

  touch = {
    id: 0,
    y: 0,
    inertia: 0,
    animation: -1
  };

  beforeUpdate = () => {
    this.isUpdatingChildren = false;
    return null;
  };

  updated() {
    this.doUpdate();
  }

  doUpdate() {
    const bounds = this.bounds;
    const contentBounds = this.contentBounds;

    if (
      (!bounds || (this.childrenChanged && this.scrollHeight === void 0)) &&
      this.$refs.content &&
      this.$refs.container
    ) {
      this.childrenChanged = false;
      this.isUpdatingChildren = true;
      const bounds = this.$refs.container.getBoundingClientRect();
      const contentBounds = this.$refs.content.getBoundingClientRect();
      const metrics = this.scrollMetrics;

      this.$emit(
        "scroll",
        this.$refs.container.scrollTop,
        metrics.scrollSpace,
        bounds,
        contentBounds
      );

      this.bounds = bounds;
      this.contentBounds = contentBounds;
    }

    // Handle scrollToOnce application
    if (
      bounds &&
      contentBounds &&
      this.$refs.container &&
      this.scrolledToOnce !== this.scrollTopOnce
    ) {
      this.scrolledToOnce = this.scrollTopOnce;
      const metrics = this.scrollMetrics;

      this.$refs.container.scrollTop = Math.max(
        Math.min(this.scrolledToOnce || 0, metrics.scrollSpace),
        0
      );

      this.top = this.$refs.container.scrollTop;

      // Broadcast for initial scroll change
      if (bounds && contentBounds && this.$refs.container) {
        const metrics = this.scrollMetrics;
        this.$emit(
          "scroll",
          this.$refs.container.scrollTop,
          metrics.scrollSpace,
          bounds,
          contentBounds
        );
      }
    }

    // Broadcast scroll metrics when the scroll height changes
    else if (
      bounds &&
      contentBounds &&
      this.$refs.container &&
      this.currentScrollHeight !== this.scrollHeight
    ) {
      this.currentScrollHeight = this.scrollHeight;
      const metrics = this.scrollMetrics;
      this.$emit(
        "scroll",
        this.$refs.container.scrollTop,
        metrics.scrollSpace,
        bounds,
        contentBounds
      );
    }
  }

  mounted() {
    if (this.$refs.content) {
      // Observe our content for changes to the DOM structure
      this.observer = new MutationObserver(() => {
        this.childrenChanged = true;
      });

      // Setup the observer
      this.observer.observe(this.$refs.content, {
        attributes: true,
        childList: true,
        characterData: true,
        subtree: true
      });
    }

    this.doUpdate();
    window.addEventListener("resize", this.handleResize);
    document.onwheel;

    // Initial scroll broadcast to indicate initial scroll position
    setTimeout(() => this.doUpdate(), 10);

    // We HAVE to manually add the event to get around the issues that exists
    // with passive event listeners.
    if (this.$refs.container) {
      this.$refs.container.addEventListener("wheel", this.handleWheel, {
        passive: false
      });

      this.$refs.container.addEventListener("touchmove", this.handleTouchMove, {
        passive: false
      });

      this.$refs.container.addEventListener(
        "touchstart",
        this.handleTouchStart
      );

      this.$refs.container.addEventListener("touchend", this.handleTouchEnd);
    }
  }

  beforeDestroy = () => {
    // Clean up
    this.observer.disconnect();
  };

  get scrollMetrics() {
    const bounds = this.bounds;
    const contentBounds = this.contentBounds;
    let barHeight = 0;
    let barRatio = 1;
    let barSpace = 0;
    let scrollSpace = 0;

    if (bounds && contentBounds) {
      barRatio = bounds.height / contentBounds.height;
      barHeight = barRatio * bounds.height;
      barHeight = Math.max(barHeight, 30);
      barHeight = Math.min(barHeight, bounds.height);
    }

    if (barRatio < 1 && bounds && contentBounds) {
      barSpace = bounds.height - barHeight;
      scrollSpace = contentBounds.height - bounds.height;
    }

    return {
      barHeight,
      barRatio,
      barSpace,
      scrollSpace
    };
  }

  get contentStyle() {
    return {
      height: `${this.scrollHeight}px`,
      flex: `1 1 ${this.scrollHeight}px`,
      minHeight: `${this.scrollHeight}px`
    };
  }

  get barStyle() {
    let barTop = this.top;
    const metrics = this.scrollMetrics;
    barTop += (this.top / metrics.scrollSpace) * metrics.barSpace;

    if (isNaN(barTop)) {
      barTop = 0;
    }

    return {
      top: `${barTop}px`,
      height:
        ((this.isOpen || this.touch.animation >= 0) &&
          this.bounds &&
          metrics.barRatio < 1) ||
        this.isDragging
          ? `${metrics.barHeight}px`
          : `0px`,
      opacity:
        ((this.isOpen || this.touch.animation >= 0) &&
          this.bounds &&
          metrics.barRatio < 1) ||
        this.isDragging
          ? "1"
          : "0",
      left: this.side === ScrollBarSide.LEFT ? "0px" : void 0,
      right: this.side === ScrollBarSide.RIGHT ? "0px" : void 0
    };
  }

  init = () => {
    const bounds = this.bounds;
    const contentBounds = this.contentBounds;

    // Don't trigger an initial scroll event until there is something able to
    // scroll
    if (
      !bounds?.height ||
      !contentBounds?.height ||
      bounds.height >= contentBounds.height
    ) {
      return;
    }

    if (!this.initialized && bounds && contentBounds && this.$refs.container) {
      this.initialized = true;

      const metrics = this.scrollMetrics;
      this.$emit(
        "scroll",
        this.$refs.container.scrollTop,
        metrics.scrollSpace,
        bounds,
        contentBounds
      );
    }
  };

  handleResize = () => {
    this.bounds = void 0;
    this.contentBounds = void 0;
  };

  handleOver() {
    this.top;
    this.isOpen = true;
    delete this.bounds;
    this.doUpdate();
  }

  handleOut(e) {
    const event = e;
    let node = event.toElement || event.relatedTarget;

    while (node) {
      if (
        node.parentNode === this.$refs.container ||
        node === this.$refs.container
      ) {
        return;
      }

      node = node.parentElement;
    }

    this.top;
    this.isOpen = false;
  }

  handleTouchStart(e) {
    let touch = null;

    for (let i = 0, iMax = e.touches.length; i < iMax; ++i) {
      touch = e.touches.item(i);
      if (touch) {
        break;
      }
    }

    if (touch) {
      this.touch.y = touch.pageY;
      this.touch.id = touch.identifier;
    }

    this.top;
    this.isOpen = true;
    delete this.bounds;
    this.doUpdate();
    cancelAnimationFrame(this.touch.animation);
    this.touch.animation = -1;
  }

  handleTouchEnd(e) {
    let touch = null;
    for (let i = 0, iMax = e.touches.length; i < iMax; ++i) {
      touch = e.touches.item(i);
      if (touch) {
        if (touch.identifier === this.touch.id) break;
        touch = null;
      }
    }

    if (!touch) {
      for (let i = 0, iMax = e.targetTouches.length; i < iMax; ++i) {
        touch = e.targetTouches.item(i);
        if (touch) {
          if (touch.identifier === this.touch.id) break;
          touch = null;
        }
      }
    }

    if (!touch) {
      for (let i = 0, iMax = e.changedTouches.length; i < iMax; ++i) {
        touch = e.changedTouches.item(i);
        if (touch) {
          if (touch.identifier === this.touch.id) break;
          touch = null;
        }
      }
    }

    if (!touch) return;
    this.top;
    this.isOpen = false;

    if (Math.abs(this.touch.inertia) > 0 && this.$refs.container) {
      const bounds = this.bounds;
      const contentBounds = this.contentBounds;
      const current = this.$refs.container;
      cancelAnimationFrame(this.touch.animation);

      const animateInertia = () => {
        current.scrollTop += this.touch.inertia;
        const metrics = this.scrollMetrics;
        current.scrollTop = Math.min(current.scrollTop, metrics.scrollSpace);

        this.top = current.scrollTop;

        if (bounds && contentBounds) {
          this.$emit(
            "scroll",
            current.scrollTop,
            metrics.scrollSpace,
            bounds,
            contentBounds
          );
        }

        this.touch.inertia *= 0.95;
        if (Math.abs(this.touch.inertia) > 0.001) {
          requestAnimationFrame(animateInertia);
        } else this.touch.animation = -1;
      };

      this.touch.animation = requestAnimationFrame(animateInertia);
    }
  }

  handleTouchMove(e) {
    if (!(e.currentTarget instanceof HTMLDivElement)) return;

    const bounds = this.bounds;
    const contentBounds = this.contentBounds;
    const isOpen = this.isOpen;

    let touch = null;
    for (let i = 0, iMax = e.touches.length; i < iMax; ++i) {
      touch = e.touches.item(i);
      if (touch) {
        if (touch.identifier === this.touch.id) break;
      }
    }

    if (!touch) return;

    e.currentTarget.scrollTop += this.touch.y - touch.pageY;
    this.touch.inertia = this.touch.y - touch.pageY;
    if (!this.allowTouchInertia) this.touch.inertia = 0;
    this.touch.y = touch.pageY;
    const metrics = this.scrollMetrics;

    e.currentTarget.scrollTop = Math.min(
      e.currentTarget.scrollTop,
      metrics.scrollSpace
    );

    this.top = e.currentTarget.scrollTop;

    if (bounds && contentBounds) {
      this.$emit(
        "scroll",
        e.currentTarget.scrollTop,
        metrics.scrollSpace,
        bounds,
        contentBounds
      );
    }

    if (isOpen && bounds && metrics.barRatio < 1) {
      e.stopPropagation?.();
      e.preventDefault?.();
    }

    cancelAnimationFrame(this.touch.animation);
  }

  handleWheel(e) {
    if (!(e.currentTarget instanceof HTMLDivElement)) return;
    const bounds = this.bounds;
    const contentBounds = this.contentBounds;
    const isOpen = this.isOpen;
    const wheel = normalizeWheel(e);
    e.currentTarget.scrollTop -= wheel.pixelY;
    const metrics = this.scrollMetrics;

    e.currentTarget.scrollTop = Math.min(
      e.currentTarget.scrollTop,
      metrics.scrollSpace
    );

    this.top = e.currentTarget.scrollTop;
    this.$forceUpdate();

    if (bounds && contentBounds) {
      this.$emit(
        "scroll",
        e.currentTarget.scrollTop,
        metrics.scrollSpace,
        bounds,
        contentBounds
      );
    }

    if (isOpen && bounds && metrics.barRatio < 1) {
      e.stopPropagation?.();
      e.preventDefault?.();
    }
  }

  handleBarDown(e) {
    const bounds = this.bounds;
    const contentBounds = this.contentBounds;
    // Once the bar is mouse downed, we begin to start the dragging process which
    // should be registered across the whole document
    const metrics = this.scrollMetrics;

    // We must calculate how much one pixel of movement would scroll the content
    const pixelScroll = metrics.scrollSpace / metrics.barSpace;
    let startY = e.clientY;
    this.isDragging = true;

    const mousemove = e => {
      const newY = e.clientY;
      const deltaY = newY - startY;
      startY = newY;

      if (this.$refs.container) {
        this.$refs.container.scrollTop += deltaY * pixelScroll;

        this.$refs.container.scrollTop = Math.min(
          this.$refs.container.scrollTop,
          metrics.scrollSpace
        );

        this.top = this.$refs.container.scrollTop;
      }

      // Prevent any event bubbling to prevent any default dragging behaviorss
      if (e.stopPropagation) e.stopPropagation();
      if (e.preventDefault) e.preventDefault();
      e.cancelBubble = true;
      e.returnValue = false;

      // Make sure the scroll info is broadcast still
      if (bounds && contentBounds && this.$refs.container) {
        this.$emit(
          "scroll",
          this.$refs.container.scrollTop,
          metrics.scrollSpace,
          bounds,
          contentBounds
        );
      }

      return false;
    };

    const mouseup = () => {
      document.removeEventListener("mousemove", mousemove);
      document.removeEventListener("mouseup", mouseup);
      this.isDragging = false;
    };

    document.addEventListener("mousemove", mousemove);
    document.addEventListener("mouseup", mouseup);
  }
}
</script>

<template>
  <div
    key="scroll-view"
    :class="['ScrollView']"
    ref="container"
    @mouseover="handleOver"
    @mouseout="handleOut"
  >
    <div
      key="scroll-content"
      ref="content"
      :class="['ScrollView__Content', contentClassName]"
      :style="contentStyle"
    >
      <slot />
    </div>
    <div
      :class="'ScrollView__Bar'"
      :style="barStyle"
      @mousedown="handleBarDown"
    />
  </div>
</template>
